def schedule_flowshop(times: list[list[int]]) -> list[int]:
    import random

    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]

    def compute_makespan(perm):
        # C[k] = completion time on machine k for current job
        C = [0] * m
        for j in perm:
            C[0] = C[0] + times[j][0]
            for k in range(1, m):
                C[k] = max(C[k], C[k-1]) + times[j][k]
        return C[m-1]

    def compute_completion_times(perm):
        # Returns full completion time matrix
        comp = [[0]*m for _ in range(len(perm))]
        for i, j in enumerate(perm):
            if i == 0:
                comp[0][0] = times[j][0]
                for k in range(1, m):
                    comp[0][k] = comp[0][k-1] + times[j][k]
            else:
                comp[i][0] = comp[i-1][0] + times[j][0]
                for k in range(1, m):
                    comp[i][k] = max(comp[i-1][k], comp[i][k-1]) + times[j][k]
        return comp

    # NEH heuristic
    def neh():
        # Sort jobs by decreasing total processing time
        totals = [(sum(times[j]), j) for j in range(n)]
        totals.sort(reverse=True)
        order = [j for _, j in totals]

        # Incrementally build the sequence
        sequence = [order[0]]
        for i in range(1, n):
            job = order[i]
            best_ms = None
            best_pos = 0
            for pos in range(len(sequence) + 1):
                trial = sequence[:pos] + [job] + sequence[pos:]
                ms = compute_makespan(trial)
                if best_ms is None or ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            sequence = sequence[:best_pos] + [job] + sequence[best_pos:]
        return sequence

    # Build initial solution with NEH
    best_perm = neh()
    best_ms = compute_makespan(best_perm)

    # Local search: insertion moves (relocate single job)
    def insertion_improvement(perm, max_iter=None):
        perm = list(perm)
        n_jobs = len(perm)
        improved = True
        iterations = 0
        while improved:
            improved = False
            if max_iter is not None and iterations >= max_iter:
                break
            iterations += 1
            for i in range(n_jobs):
                job = perm[i]
                # Remove job from position i
                new_perm = perm[:i] + perm[i+1:]
                current_ms = compute_makespan(perm)
                best_local_ms = current_ms
                best_local_pos = i
                for pos in range(len(new_perm) + 1):
                    if pos == i:
                        continue
                    trial = new_perm[:pos] + [job] + new_perm[pos:]
                    ms = compute_makespan(trial)
                    if ms < best_local_ms:
                        best_local_ms = ms
                        best_local_pos = pos
                if best_local_ms < current_ms:
                    perm = new_perm[:best_local_pos] + [job] + new_perm[best_local_pos:]
                    improved = True
                    break
        return perm, compute_makespan(perm)

    # Apply insertion improvement with iteration cap
    max_iter = max(1, min(20, 200 // n)) if n > 0 else 5
    improved_perm, improved_ms = insertion_improvement(best_perm, max_iter=max_iter)
    if improved_ms < best_ms:
        best_perm = improved_perm
        best_ms = improved_ms

    # Adjacent swap improvement pass
    def adjacent_swap_improvement(perm, max_passes=5):
        perm = list(perm)
        n_jobs = len(perm)
        for _ in range(max_passes):
            improved = False
            for i in range(n_jobs - 1):
                # Swap adjacent jobs i and i+1
                perm[i], perm[i+1] = perm[i+1], perm[i]
                ms_new = compute_makespan(perm)
                if ms_new < compute_makespan(perm[:i] + [perm[i+1]] + [perm[i]] + perm[i+2:]):
                    improved = True
                else:
                    # Swap back
                    perm[i], perm[i+1] = perm[i+1], perm[i]
            if not improved:
                break
        return perm, compute_makespan(perm)

    # More efficient adjacent swap
    def fast_adjacent_swap(perm, max_passes=10):
        perm = list(perm)
        n_jobs = len(perm)
        current_ms = compute_makespan(perm)
        for _ in range(max_passes):
            improved = False
            for i in range(n_jobs - 1):
                perm[i], perm[i+1] = perm[i+1], perm[i]
                ms_new = compute_makespan(perm)
                if ms_new < current_ms:
                    current_ms = ms_new
                    improved = True
                else:
                    perm[i], perm[i+1] = perm[i+1], perm[i]
            if not improved:
                break
        return perm, current_ms

    swap_perm, swap_ms = fast_adjacent_swap(best_perm, max_passes=min(10, max(3, 50 // n)))
    if swap_ms < best_ms:
        best_perm = swap_perm
        best_ms = swap_ms

    # For small instances, do more thorough search
    if n <= 15:
        # Additional insertion pass
        improved_perm2, improved_ms2 = insertion_improvement(best_perm, max_iter=50)
        if improved_ms2 < best_ms:
            best_perm = improved_perm2
            best_ms = improved_ms2
        # Another swap pass
        swap_perm2, swap_ms2 = fast_adjacent_swap(best_perm, max_passes=20)
        if swap_ms2 < best_ms:
            best_perm = swap_perm2
            best_ms = swap_ms2

    return best_perm
